export const UNITS_MS = { ms: 1, s: 1000, m: 60_000, h: 3_600_000 } as const;

const TOKEN = /(\d+)(ms|s|m|h)/g;

export function parseDuration(text: string): number {
  const t = text.trim();
  if (t === "") throw new Error("empty duration");
  let total = 0;
  let consumed = 0;
  for (const m of t.matchAll(TOKEN)) {
    total += Number(m[1]) * UNITS_MS[m[2] as keyof typeof UNITS_MS];
    consumed += m[0].length;
  }
  if (consumed !== t.length) throw new Error(`invalid duration: ${text}`);
  return total;
}

